The queue manager:

```typescript
import { Toast } from '@capacitor/toast';

type Position = 'top' | 'center' | 'bottom';

interface QueueItem {
  text: string;
  duration: number;
  position: Position;
  resolve: () => void;
}

class ToastQueueManager {
  private queue: QueueItem[] = [];
  private active = false;
  private drainResolvers: Array<() => void> = [];

  enqueueToast(options: {
    text: string;
    duration?: number | 'short' | 'long';
    position?: Position;
  }): Promise<void> {
    const text = options.text;
    const position: Position = options.position ?? 'bottom';
    let duration: number;
    if (options.duration === 'long') {
      duration = 3500;
    } else if (options.duration === 'short') {
      duration = 2000;
    } else if (typeof options.duration === 'number') {
      duration = options.duration;
    } else {
      duration = 2000; // default
    }

    return new Promise<void>((resolve) => {
      this.queue.push({ text, duration, position, resolve });
      this.process();
    });
  }

  private process(): void {
    if (this.active) return;
    const item = this.queue.shift();
    if (!item) {
      // Queue is empty and nothing active - resolve any pending drain promises
      this.resolveDrains();
      return;
    }
    this.active = true;
    this.displayToast(item).then(() => {
      this.active = false;
      item.resolve();
      this.process(); // Process next item
    });
  }

  private async displayToast(item: QueueItem): Promise<void> {
    // Call the real Toast.show() to create the <pwa-toast> element
    await Toast.show({
      text: item.text,
      duration: 'short', // The plugin's own duration is irrelevant; we control timing
      position: item.position,
    });

    // Find the created <pwa-toast> element
    const toastEl = document.querySelector('pwa-toast');
    if (toastEl) {
      // Set data-position attribute
      toastEl.setAttribute('data-position', item.position);
      // Set text property (plugin sets 'message', but contract requires 'text')
      (toastEl as any).text = item.text;
    }

    // Wait for the configured duration
    await new Promise<void>((resolve) => setTimeout(resolve, item.duration));

    // Remove the element
    if (toastEl && toastEl.parentNode) {
      toastEl.parentNode.removeChild(toastEl);
    }
  }

  drainToastQueue(): Promise<void> {
    if (!this.active && this.queue.length === 0) {
      return Promise.resolve();
    }
    return new Promise<void>((resolve) => {
      this.drainResolvers.push(resolve);
    });
  }

  private resolveDrains(): void {
    const resolvers = this.drainResolvers;
    this.drainResolvers = [];
    for (const resolve of resolvers) {
      resolve();
    }
  }

  getQueueState(): { pending: number; active: boolean } {
    return {
      pending: this.queue.length,
      active: this.active,
    };
  }
}
```

